import React, { useEffect, useRef } from "react";
import Menu from "./Menu";

const TopBar = () => {
  const widgetRef = useRef(null);

  useEffect(() => {
    // 1. Error Overlay bypass: Agar script error aaye toh React crash na ho
    const handleError = (e) => {
      if (e.message.includes("Script error") || e.message.includes("TradingView")) {
        e.stopImmediatePropagation();
        e.preventDefault();
      }
    };
    window.addEventListener("error", handleError);

    const container = widgetRef.current;
    if (container) {
      container.innerHTML = ""; // Purana data saaf karo

      const script = document.createElement("script");
      script.src = "https://s3.tradingview.com/external-embedding/embed-widget-tickers.js";
      script.type = "text/javascript";
      script.async = true;

      // Configuration
      script.innerHTML = JSON.stringify({
        "symbols": [
          { "proName": "FOREXCOM:NSXUSD", "title": "NIFTY 50" },
          { "proName": "INDEX:SENSEX", "title": "SENSEX" }
        ],
        "colorTheme": "light",
        "isTransparent": true,
        "showSymbolLogo": false,
        "locale": "in"
      });

      container.appendChild(script);
    }

    return () => {
      window.removeEventListener("error", handleError);
      if (container) container.innerHTML = "";
    };
  }, []);

  return (
    <div className="topbar-container" style={{ 
      display: "flex", 
      justifyContent: "space-between", 
      alignItems: "center",
      padding: "0 20px",
      borderBottom: "1px solid #eee",
      backgroundColor: "#fff",
      height: "60px"
    }}>
      {/* Widget Container */}
      <div ref={widgetRef} style={{ width: "450px", overflow: "hidden" }}></div>

      <Menu />
    </div>
  );
};

export default TopBar;
